import React from "react";
import ChartistGraph from "react-chartist";

// 1. จำลองข้อมูลที่ได้มาจาก Database (เหมือนรูปที่ 2)
const dbData = [
  { Location_Name: "วิทยาศาสตร์", TimeSlot: "09:00", MaxPeople: 5 },
  { Location_Name: "ศิลปศาสตร์", TimeSlot: "09:00", MaxPeople: 2 },
  { Location_Name: "PKY", TimeSlot: "09:00", MaxPeople: 7 },
  { Location_Name: "PKY", TimeSlot: "10:00", MaxPeople: 5 },
  { Location_Name: "PKY", TimeSlot: "11:00", MaxPeople: 2 },
  { Location_Name: "วิศวะ", TimeSlot: "12:00", MaxPeople: 1 },
  { Location_Name: "PKY", TimeSlot: "12:00", MaxPeople: 7 },
];

function Dashboard() {

  // 2. ฟังก์ชันแปลงข้อมูล Database ให้เป็น Format ของกราฟ
  const processChartData = (data) => {
    // หาช่วงเวลาทั้งหมดที่ไม่ซ้ำกัน (เพื่อทำแกน X) -> ['09:00', '10:00', '11:00', '12:00']
    const allTimeSlots = [...new Set(data.map(item => item.TimeSlot))].sort();

    // หาชื่อสถานที่ทั้งหมดที่ไม่ซ้ำกัน (เพื่อทำเป็นเส้นแต่ละสี)
    const allLocations = [...new Set(data.map(item => item.Location_Name))];

    // สร้างข้อมูล Series สำหรับแต่ละสถานที่
    const seriesData = allLocations.map(location => {
      return allTimeSlots.map(time => {
        // ค้นหาข้อมูลที่ตรงกับ สถานที่ และ เวลา นั้นๆ
        const record = data.find(d => d.Location_Name === location && d.TimeSlot === time);
        // ถ้าเจอให้ใช้ค่า MaxPeople ถ้าไม่เจอให้เป็น 0 (กราฟจะได้ไม่ขาด)
        return record ? record.MaxPeople : 0;
      });
    });

    return {
      labels: allTimeSlots, // แกน X
      series: seriesData,   // แกน Y (ข้อมูลหลายเส้น)
      legendNames: allLocations // เก็บชื่อไว้ทำ Legend (สีฟ้า, แดง, ส้ม...)
    };
  };

  const chartData = processChartData(dbData);

  // ตั้งค่า Option ของกราฟ (ให้มีจุด low/high และ padding)
  const chartOptions = {
    low: 0,
    high: 10, // ปรับตามข้อมูลสูงสุดจริง หรือเอาออกเพื่อให้ Auto
    showArea: false,
    height: "245px",
    axisX: {
      showGrid: false,
    },
    lineSmooth: true,
    showLine: true,
    showPoint: true,
    fullWidth: true,
    chartPadding: {
      right: 50
    }
  };

  return (
    <div className="content">
      <div className="container-fluid">
        <div className="row">
          <div className="col-md-12">
            <div className="card">
              <div className="header">
                <h4 className="title">Passenger Density</h4>
                <p className="category">Real-time data from database</p>
              </div>
              <div className="content">
                {/* ส่วนแสดงกราฟ */}
                <ChartistGraph
                  data={{
                    labels: chartData.labels,
                    series: chartData.series
                  }}
                  type="Line"
                  options={chartOptions}
                />

                {/* ส่วนแสดง Legend (คำอธิบายสี) ด้านล่าง */}
                <div className="footer">
                  <div className="legend">
                    {chartData.legendNames.map((name, index) => (
                      <span key={index} style={{ marginRight: '10px' }}>
                        <i className="fa fa-circle" style={{ color: getColor(index) }}></i> {name}
                      </span>
                    ))}
                  </div>
                  <hr />
                  <div className="stats">
                    <i className="fa fa-history"></i> Updated just now
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ฟังก์ชันช่วยเลือกสี (Chartist มักใช้ class ct-series-a, b, c... แต่อันนี้จำลองสีให้ดูง่ายๆ)
const getColor = (index) => {
  const colors = ['#1DC7EA', '#FB404B', '#FFA534', '#9368E9', '#87CB16'];
  return colors[index % colors.length];
}

export default Dashboard;
